use std::path::{Path, PathBuf};
use std::rc::Rc;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::OnceLock;

const FEATURE_STAGE_METADATA_JSON: &str = include_str!("../../docs/feature-stages.json");
static TEMP_WORKSPACE_COUNTER: AtomicU64 = AtomicU64::new(0);
static COMPILER_EXECUTABLE_HASH: OnceLock<Option<String>> = OnceLock::new();
static RUSTC_FINGERPRINT: OnceLock<Option<String>> = OnceLock::new();

fn unique_temp_workspace(prefix: &str) -> PathBuf {
    let sequence = TEMP_WORKSPACE_COUNTER.fetch_add(1, Ordering::Relaxed);
    std::env::temp_dir().join(format!("{prefix}-{}-{sequence}", std::process::id()))
}

fn feature_stage_metadata_json() -> &'static str {
    FEATURE_STAGE_METADATA_JSON
}

fn reorder_named_constructor_args(
    fields_by_constructor: &BTreeMap<String, Vec<String>>,
    ctor_name: &str,
    args: &[Expr],
) -> Option<Vec<Expr>> {
    let fields = fields_by_constructor.get(ctor_name)?;
    reorder_named_args_by_names(fields, args)
}

fn reorder_named_direct_call_args(
    fields_by_constructor: &BTreeMap<String, Vec<String>>,
    params_by_callable: &BTreeMap<String, Vec<String>>,
    name: &str,
    args: &[Expr],
) -> Option<Vec<Expr>> {
    if let Some(fields) = fields_by_constructor.get(name) {
        return reorder_named_args_by_names(fields, args);
    }
    let params = params_by_callable.get(name)?;
    reorder_named_args_by_names(params, args)
}

fn main() {
    // Use a large stack (64 MB) to handle deep recursion in comptime evaluation
    let builder = std::thread::Builder::new().stack_size(64 * 1024 * 1024);
    let handler = match builder.spawn(main_inner) {
        Ok(h) => h,
        Err(e) => {
            eprintln!("Fatal: failed to spawn main thread: {}", e);
            std::process::exit(1);
        }
    };
    if let Err(e) = handler.join() {
        std::panic::resume_unwind(e);
    }
}

