    fn parse_invariant_and_proof(source: &str) -> (Expr, Expr, ProofBlock, BTreeMap<String, Expr>) {
        let mut lexer = Lexer::new(source);
        let tokens = lexer.tokenize();
        let mut parser = Parser::new(tokens, source);
        let stmts = parser.parse_program().expect("parse failed");

        let (subject, predicate) = match &stmts[0] {
            Stmt::Invariant {
                subject, predicate, ..
            } => (subject.clone(), predicate.clone()),
            other => panic!("expected invariant, got {:?}", other),
        };
        let proof_block = match &stmts[1] {
            Stmt::Prove {
                proof_block: Some(block),
                ..
            } => block.clone(),
            other => panic!("expected explicit proof, got {:?}", other),
        };

        let bindings = stmts
            .iter()
            .filter_map(|stmt| match stmt {
                Stmt::Bind(Pat::Var(name), _, expr) => Some((name.clone(), expr.clone())),
                _ => None,
            })
            .collect();

        (subject, predicate, proof_block, bindings)
    }

    fn explicit_proof_statuses(source: &str) -> BTreeMap<String, ExplicitProofStatus> {
        let mut lexer = Lexer::new(source);
        let tokens = lexer.tokenize();
        let mut parser = Parser::new(tokens, source);
        let stmts = parser.parse_program().expect("parse failed");
        explicit_proof_statuses_for_stmts(&stmts)
    }

    fn proof_bindings_for_stmts(stmts: &[Stmt]) -> BTreeMap<String, Expr> {
        stmts
            .iter()
            .filter_map(|stmt| match stmt {
                Stmt::Bind(Pat::Var(name), _, expr) => Some((name.clone(), expr.clone())),
                _ => None,
            })
            .collect()
    }

    fn smt_skip_reason_for_named_invariant(source: &str, inv_name: &str) -> Option<String> {
        let mut lexer = Lexer::new(source);
        let tokens = lexer.tokenize();
        let mut parser = Parser::new(tokens, source);
        let stmts = parser.parse_program().expect("parse failed");

        let mut ctor_to_type = BTreeMap::new();
        let mut invariants = BTreeMap::new();
        let mut bindings = BTreeMap::new();
        let mut functions = Vec::new();

        for stmt in &stmts {
            match stmt {
                Stmt::TypeDecl(TypeDecl::ADT { name, variants, .. }) => {
                    for variant in variants {
                        ctor_to_type.insert(variant.name.clone(), name.clone());
                    }
                }
                Stmt::Invariant {
                    name,
                    subject,
                    predicate,
                } => {
                    invariants.insert(name.clone(), (subject.clone(), predicate.clone()));
                }
                Stmt::Bind(Pat::Var(name), _, expr) => {
                    bindings.insert(name.clone(), expr.clone());
                }
                Stmt::Defn(Defn::Fn {
                    name,
                    params,
                    ret_ty,
                    body,
                    ..
                }) => {
                    functions.push((name.clone(), params.clone(), ret_ty.clone(), body.clone()));
                }
                _ => {}
            }
        }

        let (subject_expr, pred_expr) = invariants
            .get(inv_name)
            .cloned()
            .unwrap_or_else(|| panic!("missing invariant {}", inv_name));
        let fn_names: BTreeSet<String> = functions.iter().map(|(n, _, _, _)| n.clone()).collect();
        let ctor_names: BTreeSet<String> = ctor_to_type.keys().cloned().collect();
        let function_map: BTreeMap<String, (Vec<Param>, Option<Ty>, Expr)> = functions
            .iter()
            .map(|(name, params, ret_ty, body)| {
                (name.clone(), (params.clone(), ret_ty.clone(), body.clone()))
            })
            .collect();
        let ordered_vars = ordered_smt_free_vars_for_invariant(
            &pred_expr,
            &subject_expr,
            &bindings,
            &fn_names,
            &ctor_names,
        );

        smt_skip_reason_for_invariant(
            &pred_expr,
            &subject_expr,
            &ordered_vars,
            &bindings,
            &function_map,
            &ctor_names,
        )
    }

    fn json_string_array(value: &serde_json::Value) -> Vec<String> {
        value
            .as_array()
            .expect("expected JSON array")
            .iter()
            .map(|item| item.as_str().expect("expected JSON string").to_string())
            .collect()
    }

    fn parse_feature_stage_frontmatter(source: &str) -> Option<(String, Vec<String>)> {
        let source = source.strip_prefix("---\n")?;
        let end = source.find("\n---\n")?;
        let frontmatter = &source[..end];
        let mut stage = None;
        let mut surfaces = Vec::new();
        let mut in_surfaces = false;

        for line in frontmatter.lines() {
            let trimmed = line.trim();
            if let Some(raw_stage) = trimmed.strip_prefix("feature_stage:") {
                stage = Some(raw_stage.trim().to_string());
                in_surfaces = false;
            } else if trimmed == "feature_stage_surfaces:" {
                in_surfaces = true;
            } else if in_surfaces {
                if let Some(surface) = trimmed.strip_prefix("- ") {
                    surfaces.push(surface.trim().to_string());
                } else if !trimmed.is_empty() {
                    in_surfaces = false;
                }
            }
        }

        stage.map(|stage| (stage, surfaces))
    }

    fn feature_stage_document_expectations() -> BTreeMap<String, (String, Vec<String>)> {
        let metadata: serde_json::Value =
            serde_json::from_str(feature_stage_metadata_json()).expect("stage metadata is JSON");
        metadata["documents"]
            .as_array()
            .expect("metadata documents must be an array")
            .iter()
            .map(|doc| {
                let path = doc["path"].as_str().expect("document path").to_string();
                let stage = doc["stage"].as_str().expect("document stage").to_string();
                let surfaces = json_string_array(&doc["surfaces"]);
                (path, (stage, surfaces))
            })
            .collect()
    }

    #[test]
    fn feature_stage_metadata_json_is_valid() {
        let metadata: serde_json::Value =
            serde_json::from_str(feature_stage_metadata_json()).expect("valid stage metadata JSON");
        assert_eq!(metadata["schema"], "futuruna.feature-stages.v1");
        assert_eq!(metadata["schema_version"], 1);

        let stage_values = metadata["stage_values"]
            .as_object()
            .expect("stage_values object");
        for stage in [
            "stable",
            "preview",
            "experimental",
            "unstable-internal",
            "mixed",
        ] {
            assert!(stage_values.contains_key(stage), "missing stage {}", stage);
        }

        let surfaces: BTreeSet<String> = metadata["surfaces"]
            .as_array()
            .expect("surfaces array")
            .iter()
            .map(|surface| surface["id"].as_str().expect("surface id").to_string())
            .collect();
        assert!(surfaces.contains("core-language-syntax"));
        assert!(surfaces.contains("first-run-project-initialization"));
        assert!(surfaces.contains("solver-assisted-verification"));
        assert!(surfaces.contains("solver-backed-exploration"));

        let exploration = metadata["surfaces"]
            .as_array()
            .expect("surfaces array")
            .iter()
            .find(|surface| surface["id"] == "solver-backed-exploration")
            .expect("solver-backed exploration surface");
        assert_eq!(exploration["kind"], "verification");
        assert_eq!(exploration["stage"], "experimental");

        let commands = metadata["commands"].as_array().expect("commands array");
        assert!(
            !commands.iter().any(|command| command["name"] == "explore"),
            "the dedicated explore command must not be advertised before it exists"
        );
        assert!(commands.iter().any(|command| {
            command["name"] == "feature-stages" && command["stage"] == "stable"
        }));
        assert!(commands
            .iter()
            .any(|command| { command["name"] == "from-rust" && command["stage"] == "stable" }));
        assert!(commands.iter().any(|command| {
            command["name"] == "init"
                && command["stage"] == "stable"
                && command["surface"] == "first-run-project-initialization"
        }));

        for command in commands {
            let surface = command["surface"].as_str().expect("command surface");
            assert!(
                surfaces.contains(surface),
                "command references unknown surface {}",
                surface
            );
        }
    }

    #[test]
    fn reference_and_tutorial_docs_match_feature_stage_metadata() {
        let expected = feature_stage_document_expectations();
        let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
        let mut seen = BTreeSet::new();

        for dir in ["docs/reference", "docs/tutorial"] {
            let dir_path = manifest_dir.join(dir);
            for entry in std::fs::read_dir(&dir_path).expect("read docs directory") {
                let path = entry.expect("read docs entry").path();
                if path.extension().and_then(|ext| ext.to_str()) != Some("md") {
                    continue;
                }
                let relative = path
                    .strip_prefix(manifest_dir)
                    .expect("doc path under manifest")
                    .to_string_lossy()
                    .replace('\\', "/");
                let source = std::fs::read_to_string(&path).expect("read doc source");
                let actual = parse_feature_stage_frontmatter(&source)
                    .unwrap_or_else(|| panic!("{} is missing feature stage frontmatter", relative));
                let expected_for_doc = expected
                    .get(&relative)
                    .unwrap_or_else(|| panic!("{} missing from feature stage metadata", relative));

                assert_eq!(
                    &actual.0, &expected_for_doc.0,
                    "{} has mismatched feature stage",
                    relative
                );
                assert_eq!(
                    &actual.1, &expected_for_doc.1,
                    "{} has mismatched feature surfaces",
                    relative
                );
                seen.insert(relative);
            }
        }

        for path in expected.keys().filter(|path| {
            path.starts_with("docs/reference/") || path.starts_with("docs/tutorial/")
        }) {
            assert!(
                seen.contains(path),
                "{} metadata has no matching doc file",
                path
            );
        }
    }

    #[test]
    fn registry_path_stays_next_to_source_file() {
        let temp_name = format!(
            "futuruna_registry_path_{}_{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        );
        let temp_dir = std::env::temp_dir().join(temp_name);
        std::fs::create_dir_all(&temp_dir).unwrap();
        let source_path = temp_dir.join("registry_probe.runa");
        std::fs::write(&source_path, "> square(x: Int) -> Int { x * x }\n").unwrap();

        let source = std::fs::read_to_string(&source_path).unwrap();
        update_registry(&source, source_path.to_str().unwrap());

        let expected = temp_dir.join("registry_probe.registry.json");
        assert!(expected.exists(), "expected registry next to source file");
        assert!(
            !std::path::Path::new("registry_probe.registry.json").exists(),
            "registry should not be written into the caller working directory"
        );

        let _ = std::fs::remove_file(&expected);
        let _ = std::fs::remove_file("registry_probe.registry.json");
        let _ = std::fs::remove_dir_all(&temp_dir);
    }

