    #[test]
    fn ownership_analysis_simple() {
        // Parse "= x = a + a" — 'a' used twice → should have count 2
        let source = "= x = a + a";
        let mut lexer = Lexer::new(source);
        let tokens = lexer.tokenize();
        let mut parser = Parser::new(tokens, source);
        let stmts = parser.parse_program().expect("parse failed");
        if let Stmt::Bind(_, _, ref expr) = stmts[0] {
            let analysis = OwnershipAnalysis::analyze_simple(expr);
            assert_eq!(
                analysis.var_uses.get("a").copied().unwrap_or(0),
                2,
                "expected 'a' used twice"
            );
        } else {
            panic!("expected Bind statement");
        }
    }

    #[test]
    fn var_mode_clone_for_multi_use() {
        // If a non-Copy var has consuming_uses > 1, it should be Clone
        let analysis = OwnershipAnalysis {
            var_uses: [("s".into(), 2)].into(),
            consuming_uses: [("s".into(), 2)].into(),
        };
        // Simulate what emit_expr does: multi-use non-Copy → Clone
        let mode = if analysis.consuming_uses.get("s").copied().unwrap_or(0) > 1 {
            VarMode::Clone
        } else {
            VarMode::Move
        };
        assert_eq!(mode, VarMode::Clone);
    }

    #[test]
    fn ownership_analysis_counts_invariant_row_reuse() {
        let source = "\
= duplicate_bundle = checked_bundle()\n\
= duplicate_state = may_become_state(duplicate_bundle)\n\
| duplicate_evidence_rejects: duplicate_state -> duplicate_bundle.conserved == 0 && duplicate_state.admitted == 0\n";
        let mut lexer = Lexer::new(source);
        let tokens = lexer.tokenize();
        let mut parser = Parser::new(tokens, source);
        let stmts = parser.parse_program().expect("parse failed");
        let stmt_refs: Vec<&Stmt> = stmts.iter().collect();
        let analysis = OwnershipAnalysis::analyze_stmt_refs(&stmt_refs, &BTreeMap::new());
        assert!(
            analysis
                .var_uses
                .get("duplicate_bundle")
                .copied()
                .unwrap_or(0)
                >= 2,
            "invariant predicate should count duplicate_bundle as a later use"
        );
        assert!(
            analysis
                .consuming_uses
                .get("duplicate_bundle")
                .copied()
                .unwrap_or(0)
                >= 2,
            "invariant predicate should force clone before constructor move"
        );
    }

    #[test]
    fn ownership_stmt_traversal_counts_expression_bearing_children() {
        fn param(name: &str) -> Param {
            Param {
                name: name.to_string(),
                ty: None,
                inout: false,
            }
        }

        fn owned_expr(name: &str) -> Expr {
            ExprKind::App(
                Box::new(ExprKind::Var("consume".to_string()).into()),
                vec![ExprKind::Var(name.to_string()).into()],
            )
            .into()
        }

        fn expr_stmt(name: &str) -> Stmt {
            Stmt::Expr(owned_expr(name))
        }

        let stmts = vec![
            Stmt::Defn(Defn::Fn {
                name: "fn_visit".to_string(),
                params: vec![],
                ret_ty: None,
                effects: vec![],
                body: owned_expr("fn_body"),
            }),
            Stmt::Defn(Defn::Actor {
                name: "ActorVisit".to_string(),
                state_param: param("state"),
                handlers: vec![Handler {
                    msg_pat: Pat::Wild,
                    body: owned_expr("actor_body"),
                }],
            }),
            Stmt::Defn(Defn::Module {
                name: "ModuleVisit".to_string(),
                body: vec![expr_stmt("module_body")],
            }),
            Stmt::TypeDecl(TypeDecl::ADT {
                name: "MethodCarrier".to_string(),
                params: vec![],
                variants: vec![],
                methods: vec![Defn::Fn {
                    name: "method_visit".to_string(),
                    params: vec![],
                    ret_ty: None,
                    effects: vec![],
                    body: owned_expr("adt_method_body"),
                }],
                except_from: None,
            }),
            Stmt::TypeDecl(TypeDecl::WhenType {
                name: "WhenCarrier".to_string(),
                condition: owned_expr("when_condition"),
                variants: vec![],
                except_from: None,
            }),
            Stmt::TypeDecl(TypeDecl::TraitDecl {
                name: "TraitVisit".to_string(),
                params: vec![],
                methods: vec![TraitMethod {
                    name: "default_visit".to_string(),
                    params: vec![],
                    ret_ty: None,
                    default_body: Some(owned_expr("trait_default_body")),
                }],
            }),
            Stmt::TypeDecl(TypeDecl::ImplBlock {
                trait_name: "TraitVisit".to_string(),
                for_type: "MethodCarrier".to_string(),
                methods: vec![Defn::Fn {
                    name: "impl_visit".to_string(),
                    params: vec![],
                    ret_ty: None,
                    effects: vec![],
                    body: owned_expr("impl_body"),
                }],
            }),
            Stmt::Rule(Rule::Clause {
                head: owned_expr("rule_head"),
                body: Some(owned_expr("rule_body")),
            }),
            Stmt::Rule(Rule::Default {
                head: owned_expr("default_head"),
                value: owned_expr("default_value"),
                condition: Some(owned_expr("default_condition")),
            }),
            Stmt::Rule(Rule::Exception {
                label: "exception_visit".to_string(),
                head: owned_expr("exception_head"),
                value: owned_expr("exception_value"),
                condition: Some(owned_expr("exception_condition")),
            }),
            Stmt::Rule(Rule::ReactiveScope {
                name: "ScopeVisit".to_string(),
                body: vec![expr_stmt("scope_body")],
            }),
            Stmt::Annot("audit".to_string(), vec![owned_expr("annot_arg")]),
            Stmt::Bind(Pat::Var("bound".to_string()), None, owned_expr("bind_rhs")),
            Stmt::MonadicBind(
                Pat::Var("monadic".to_string()),
                None,
                owned_expr("monadic_rhs"),
            ),
            Stmt::For(
                "item".to_string(),
                owned_expr("for_iter"),
                vec![expr_stmt("for_body")],
            ),
            Stmt::While(owned_expr("while_cond"), vec![expr_stmt("while_body")]),
            Stmt::Send(owned_expr("send_target"), owned_expr("send_msg")),
            Stmt::StreamBind("stream_visit".to_string(), owned_expr("stream_rhs")),
            Stmt::StreamSub(
                owned_expr("stream_sub_expr"),
                vec![MatchArm {
                    pat: Pat::Wild,
                    guard: Some(owned_expr("stream_sub_guard")),
                    body: owned_expr("stream_sub_body"),
                }],
            ),
            Stmt::Invariant {
                name: "invariant_visit".to_string(),
                subject: owned_expr("invariant_subject"),
                predicate: owned_expr("invariant_predicate"),
            },
            Stmt::Prove {
                name: "prove_visit".to_string(),
                proof_block: None,
                capture: None,
                pass_block: Some(vec![expr_stmt("prove_pass")]),
                else_block: Some(vec![expr_stmt("prove_else")]),
            },
            Stmt::Assert("Fact".to_string(), vec![owned_expr("assert_arg")]),
            Stmt::Retract("Fact".to_string(), vec![owned_expr("retract_arg")]),
            expr_stmt("expr_stmt"),
        ];

        let stmt_refs: Vec<&Stmt> = stmts.iter().collect();
        let analysis = OwnershipAnalysis::analyze_stmt_refs(&stmt_refs, &BTreeMap::new());
        let expected = [
            "fn_body",
            "actor_body",
            "module_body",
            "adt_method_body",
            "when_condition",
            "trait_default_body",
            "impl_body",
            "rule_head",
            "rule_body",
            "default_head",
            "default_value",
            "default_condition",
            "exception_head",
            "exception_value",
            "exception_condition",
            "scope_body",
            "annot_arg",
            "bind_rhs",
            "monadic_rhs",
            "for_iter",
            "for_body",
            "while_cond",
            "while_body",
            "send_target",
            "send_msg",
            "stream_rhs",
            "stream_sub_expr",
            "stream_sub_guard",
            "stream_sub_body",
            "invariant_subject",
            "invariant_predicate",
            "prove_pass",
            "prove_else",
            "assert_arg",
            "retract_arg",
            "expr_stmt",
        ];

        for name in expected {
            assert!(
                analysis.var_uses.get(name).copied().unwrap_or(0) >= 1,
                "var-use traversal missed `{}`",
                name
            );
            assert!(
                analysis.consuming_uses.get(name).copied().unwrap_or(0) >= 1,
                "consuming-use traversal missed `{}`",
                name
            );
        }
    }

    #[derive(Debug)]
    struct AstPassCoverageCase {
        label: &'static str,
        stmt: Stmt,
        ownership_markers: Vec<&'static str>,
        import_expansion: ImportedStmtExpansion,
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    enum FirPhaseCoverage {
        VisitsFirExpressions,
        IntentionallyIgnored,
    }

    #[derive(Debug)]
    struct FirPassCoverageCase {
        label: &'static str,
        stmt: FirStmt,
        coverage: FirPhaseCoverage,
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
    enum CompilerPassId {
        TypeChecking,
        OwnershipUseAnalysis,
        ImportResolution,
        FirLowering,
        RustCodegen,
    }

    impl CompilerPassId {
        fn label(self) -> &'static str {
            match self {
                CompilerPassId::TypeChecking => "Type checking diagnostics",
                CompilerPassId::OwnershipUseAnalysis => "Ownership/use analysis",
                CompilerPassId::ImportResolution => "Import resolution",
                CompilerPassId::FirLowering => "FIR lowering",
                CompilerPassId::RustCodegen => "Rust codegen",
            }
        }
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
    enum ContractSurface {
        Canary,
        Check,
        CheckCodegen,
        Differential,
        EmitFir,
        EmitImports,
        EmitRust,
        Expect,
        Roundtrip,
        Run,
    }

    #[derive(Debug)]
    struct ContractFixture {
        path: &'static str,
        surfaces: &'static [ContractSurface],
    }

    #[derive(Debug)]
    enum PassCoverageExpectation {
        AstOwnership {
            row: &'static str,
            markers: &'static [&'static str],
        },
        AstImportExpansion {
            row: &'static str,
            expansion: ImportedStmtExpansion,
        },
        FirPhase {
            row: &'static str,
            markers: &'static [&'static str],
        },
        FixtureText {
            path: &'static str,
            marker: &'static str,
        },
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    enum TraversalAuditKind {
        CanonicalAstWalker,
        CanonicalFirWalker,
        ExhaustiveSemantic,
        StatementClassifier,
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    enum ContractSourceFile {
        LibRs,
        RunaRs,
    }

    impl ContractSourceFile {
        fn label(self) -> &'static str {
            match self {
                ContractSourceFile::LibRs => "src/lib.rs",
                ContractSourceFile::RunaRs => "src/bin/runa.rs",
            }
        }

        fn text(self) -> &'static str {
            match self {
                ContractSourceFile::LibRs => include_str!("../lib.rs"),
                ContractSourceFile::RunaRs => include_str!("runa.rs"),
            }
        }
    }

    #[derive(Debug)]
    struct TraversalAudit {
        path: &'static str,
        kind: TraversalAuditKind,
        source: ContractSourceFile,
        evidence_marker: &'static str,
        reason: &'static str,
    }

    #[derive(Debug)]
    struct CompilerPassContract {
        id: CompilerPassId,
        input_phase: &'static str,
        output_phase: &'static str,
        owned_invariants: &'static [&'static str],
        traversal_expectation: &'static str,
        module_leak_guard: &'static str,
        traversal_audit: Vec<TraversalAudit>,
        coverage: Vec<PassCoverageExpectation>,
        fixtures: Vec<ContractFixture>,
    }

