    fn coverage_param(name: &str) -> Param {
        Param {
            name: name.to_string(),
            ty: None,
            inout: false,
        }
    }

    fn coverage_expr(name: &str) -> Expr {
        ExprKind::App(
            Box::new(ExprKind::Var("consume".to_string()).into()),
            vec![ExprKind::Var(name.to_string()).into()],
        )
        .into()
    }

    fn watch_expr(type_name: &str) -> Expr {
        ExprKind::App(
            Box::new(ExprKind::Var("watch".to_string()).into()),
            vec![ExprKind::Var(type_name.to_string()).into()],
        )
        .into()
    }

    fn coverage_expr_stmt(name: &str) -> Stmt {
        Stmt::Expr(coverage_expr(name))
    }

    fn coverage_explore_stmt() -> Stmt {
        Stmt::Explore(ExploreQuery {
            name: Some("coverage_query".to_string()),
            over: ExploreOver {
                rule_name: "coverage_rule".to_string(),
                inputs: vec![],
                span: Span::dummy(),
            },
            polarity: ExplorePolarity::Matches,
            bounds: vec![
                ExploreBound::Domain {
                    name: "axis".to_string(),
                    domain: coverage_expr("explore_domain"),
                    span: Span::dummy(),
                },
                ExploreBound::Value {
                    name: "derived".to_string(),
                    value: coverage_expr("explore_value"),
                    span: Span::dummy(),
                },
                ExploreBound::Where {
                    predicate: coverage_expr("explore_where"),
                    span: Span::dummy(),
                },
            ],
            boundary: Some(ExploreBoundary {
                axis: "axis".to_string(),
                step: coverage_expr("explore_step"),
                span: Span::dummy(),
            }),
            output: ExploreOutput {
                key: vec![ExploreOutputField {
                    name: "key".to_string(),
                    value: coverage_expr("explore_key"),
                    span: Span::dummy(),
                }],
                show: vec![ExploreOutputField {
                    name: "shown".to_string(),
                    value: coverage_expr("explore_show"),
                    span: Span::dummy(),
                }],
                representative: ExploreRepresentative::Maximize {
                    objective: coverage_expr("explore_representative"),
                    span: Span::dummy(),
                },
                span: Span::dummy(),
            },
            span: Span::dummy(),
        })
    }

    fn stmt_variant_label(stmt: &Stmt) -> &'static str {
        match stmt {
            Stmt::Defn(_) => "Defn",
            Stmt::TypeDecl(_) => "TypeDecl",
            Stmt::Rule(_) => "Rule",
            Stmt::Use(_) => "Use",
            Stmt::Import(_) => "Import",
            Stmt::QualifiedImport(_, _) => "QualifiedImport",
            Stmt::HashImport(_, _) => "HashImport",
            Stmt::Depend(_, _) => "Depend",
            Stmt::RustBlock(_) => "RustBlock",
            Stmt::Annot(_, _) => "Annot",
            Stmt::Bind(_, _, _) => "Bind",
            Stmt::MonadicBind(_, _, _) => "MonadicBind",
            Stmt::For(_, _, _) => "For",
            Stmt::While(_, _) => "While",
            Stmt::Send(_, _) => "Send",
            Stmt::StreamBind(_, _) => "StreamBind",
            Stmt::StreamSub(_, _) => "StreamSub",
            Stmt::Invariant { .. } => "Invariant",
            Stmt::Prove { .. } => "Prove",
            Stmt::Explore(_) => "Explore",
            Stmt::Assert(_, _) => "Assert",
            Stmt::Retract(_, _) => "Retract",
            Stmt::Abort => "Abort",
            Stmt::Expr(_) => "Expr",
        }
    }

    fn type_decl_variant_label(decl: &TypeDecl) -> &'static str {
        match decl {
            TypeDecl::ADT { .. } => "ADT",
            TypeDecl::WhenType { .. } => "WhenType",
            TypeDecl::EffectDecl { .. } => "EffectDecl",
            TypeDecl::TraitDecl { .. } => "TraitDecl",
            TypeDecl::ImplBlock { .. } => "ImplBlock",
            TypeDecl::RuleScope { .. } => "RuleScope",
        }
    }

