    fn collect_fir_visitor_vars_from_stmt(stmt: &FirStmt, vars: &mut BTreeSet<String>) {
        walk_fir_stmt(stmt, &mut |child| {
            if let FirChild::Expr(expr) = child {
                if let FirExprKind::Var(name, _) = &expr.kind {
                    vars.insert(name.clone());
                }
            }
        });
    }

    #[test]
    fn canonical_fir_walk_reaches_phase_coverage_markers() {
        let rows = fir_phase_coverage_cases();
        let expected: &[(&str, &[&str])] = &[
            ("FirStmt::Defn::Actor", &["actor_body"]),
            ("FirStmt::Defn::Module", &["module_body"]),
            ("FirStmt::For", &["for_iter", "for_body"]),
            ("FirStmt::Send", &["send_target", "send_msg"]),
            (
                "FirStmt::StreamSub",
                &["stream_sub_expr", "stream_sub_guard", "stream_sub_body"],
            ),
            (
                "FirStmt::Invariant",
                &["invariant_subject", "invariant_predicate"],
            ),
            ("FirStmt::Prove", &["prove_pass", "prove_else"]),
        ];

        for (label, markers) in expected {
            let row = rows
                .iter()
                .find(|row| row.label == *label)
                .unwrap_or_else(|| panic!("missing FIR coverage row {label}"));
            let mut vars = BTreeSet::new();
            collect_fir_visitor_vars_from_stmt(&row.stmt, &mut vars);
            for marker in *markers {
                assert!(
                    vars.contains(*marker),
                    "canonical FIR visitor missed `{}` in {}; visited {:?}",
                    marker,
                    label,
                    vars
                );
            }
        }
    }

    #[test]
    fn rust_codegen_watch_collection_reaches_nested_ast_shapes() {
        let stmts = vec![
            Stmt::Invariant {
                name: "watch_invariant".to_string(),
                subject: watch_expr("InvariantFact"),
                predicate: coverage_expr("invariant_predicate"),
            },
            Stmt::Prove {
                name: "watch_prove".to_string(),
                proof_block: None,
                capture: None,
                pass_block: Some(vec![Stmt::Expr(watch_expr("ProvePassFact"))]),
                else_block: Some(vec![Stmt::StreamSub(
                    watch_expr("StreamFact"),
                    vec![MatchArm {
                        pat: Pat::Wild,
                        guard: Some(watch_expr("GuardFact")),
                        body: watch_expr("BodyFact"),
                    }],
                )]),
            },
            Stmt::Expr(ExprKind::Block(vec![Stmt::Expr(watch_expr("BlockFact"))]).into()),
        ];

        let mut watched = BTreeSet::new();
        RustCodegen::collect_watch_type_names_from_stmt_list(&stmts, &mut watched);
        let expected: BTreeSet<String> = [
            "InvariantFact",
            "ProvePassFact",
            "StreamFact",
            "GuardFact",
            "BodyFact",
            "BlockFact",
        ]
        .into_iter()
        .map(str::to_string)
        .collect();

        assert_eq!(watched, expected);
    }

    #[test]
    fn compiler_pass_coverage_matrix_classifies_stmt_type_decl_and_fir_variants() {
        let ast_rows = ast_pass_coverage_cases();
        let expected_stmt_variants: BTreeSet<_> = [
            "Defn",
            "TypeDecl",
            "Rule",
            "Use",
            "Import",
            "QualifiedImport",
            "HashImport",
            "Depend",
            "RustBlock",
            "Annot",
            "Bind",
            "MonadicBind",
            "For",
            "While",
            "Send",
            "StreamBind",
            "StreamSub",
            "Invariant",
            "Prove",
            "Explore",
            "Assert",
            "Retract",
            "Abort",
            "Expr",
        ]
        .into_iter()
        .collect();
        let observed_stmt_variants: BTreeSet<_> = ast_rows
            .iter()
            .map(|row| stmt_variant_label(&row.stmt))
            .collect();
        assert_eq!(observed_stmt_variants, expected_stmt_variants);

        let expected_type_decl_variants: BTreeSet<_> = [
            "ADT",
            "WhenType",
            "EffectDecl",
            "TraitDecl",
            "ImplBlock",
            "RuleScope",
        ]
        .into_iter()
        .collect();
        let observed_type_decl_variants: BTreeSet<_> = ast_rows
            .iter()
            .filter_map(|row| match &row.stmt {
                Stmt::TypeDecl(decl) => Some(type_decl_variant_label(decl)),
                _ => None,
            })
            .collect();
        assert_eq!(observed_type_decl_variants, expected_type_decl_variants);

        for row in &ast_rows {
            assert_eq!(
                RustCodegen::classify_imported_stmt_for_expansion(&row.stmt),
                row.import_expansion,
                "import normalization coverage mismatch for {}",
                row.label
            );

            let analysis = OwnershipAnalysis::analyze_stmt_refs(&[&row.stmt], &BTreeMap::new());
            for marker in &row.ownership_markers {
                assert!(
                    analysis.var_uses.get(*marker).copied().unwrap_or(0) >= 1,
                    "ownership var-use traversal missed `{}` in {}",
                    marker,
                    row.label
                );
                assert!(
                    analysis.consuming_uses.get(*marker).copied().unwrap_or(0) >= 1,
                    "ownership consuming-use traversal missed `{}` in {}",
                    marker,
                    row.label
                );
            }
        }

        let fir_rows = fir_phase_coverage_cases();
        let expected_fir_stmt_variants: BTreeSet<_> = [
            "Defn",
            "TypeDecl",
            "Rule",
            "Use",
            "Import",
            "QualifiedImport",
            "HashImport",
            "Depend",
            "RustBlock",
            "Annot",
            "Bind",
            "MonadicBind",
            "For",
            "Send",
            "StreamBind",
            "StreamSub",
            "Invariant",
            "Prove",
            "Explore",
            "Assert",
            "Retract",
            "Abort",
            "Expr",
        ]
        .into_iter()
        .collect();
        let observed_fir_stmt_variants: BTreeSet<_> = fir_rows
            .iter()
            .map(|row| fir_stmt_variant_label(&row.stmt))
            .collect();
        assert_eq!(observed_fir_stmt_variants, expected_fir_stmt_variants);

        let expected_fir_defn_variants: BTreeSet<_> =
            ["Fn", "Actor", "Module"].into_iter().collect();
        let observed_fir_defn_variants: BTreeSet<_> = fir_rows
            .iter()
            .filter_map(|row| match &row.stmt {
                FirStmt::Defn(defn) => Some(fir_defn_variant_label(defn)),
                _ => None,
            })
            .collect();
        assert_eq!(observed_fir_defn_variants, expected_fir_defn_variants);

        for row in &fir_rows {
            let panicked = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                assert_fir_stmt_phase_validated(&row.stmt);
            }))
            .is_err();
            match row.coverage {
                FirPhaseCoverage::VisitsFirExpressions => assert!(
                    panicked,
                    "FIR phase validation failed to visit invalid expression in {}",
                    row.label
                ),
                FirPhaseCoverage::IntentionallyIgnored => assert!(
                    !panicked,
                    "FIR phase validation unexpectedly visited intentionally ignored {}",
                    row.label
                ),
            }
        }
    }

    fn contract_fixture_text(path: &str) -> String {
        let full_path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(path);
        std::fs::read_to_string(&full_path)
            .unwrap_or_else(|err| panic!("failed to read contract fixture `{path}`: {err}"))
    }

    #[test]
    fn compiler_pass_contracts_cover_required_passes_and_evidence() {
        let contracts = compiler_pass_contracts();
        let required: BTreeSet<_> = [
            CompilerPassId::TypeChecking,
            CompilerPassId::OwnershipUseAnalysis,
            CompilerPassId::ImportResolution,
            CompilerPassId::FirLowering,
            CompilerPassId::RustCodegen,
        ]
        .into_iter()
        .collect();
        let observed: BTreeSet<_> = contracts.iter().map(|contract| contract.id).collect();
        assert!(
            required.is_subset(&observed),
            "missing required compiler pass contracts: required={required:?} observed={observed:?}"
        );
        assert_eq!(
            observed.len(),
            contracts.len(),
            "duplicate compiler pass contract ids"
        );

        for contract in &contracts {
            let label = contract.id.label();
            assert!(
                !contract.input_phase.trim().is_empty(),
                "{label} missing input phase"
            );
            assert!(
                !contract.output_phase.trim().is_empty(),
                "{label} missing output phase"
            );
            assert!(
                !contract.owned_invariants.is_empty(),
                "{label} missing owned invariants"
            );
            assert!(
                !contract.traversal_expectation.trim().is_empty(),
                "{label} missing traversal expectation"
            );
            assert!(
                !contract.module_leak_guard.trim().is_empty(),
                "{label} missing module/import leak guard"
            );
            assert!(
                !contract.traversal_audit.is_empty(),
                "{label} missing traversal audit rows"
            );
            assert!(
                !contract.coverage.is_empty(),
                "{label} has no representative coverage markers"
            );
            assert!(
                !contract.fixtures.is_empty(),
                "{label} has no representative fixtures"
            );

            for invariant in contract.owned_invariants {
                assert!(
                    !invariant.trim().is_empty(),
                    "{label} has an empty invariant row"
                );
            }
            for audit in &contract.traversal_audit {
                assert!(
                    !audit.path.trim().is_empty(),
                    "{label} has empty traversal audit path"
                );
                assert!(
                    !audit.evidence_marker.trim().is_empty(),
                    "{label} traversal audit {} has empty source marker",
                    audit.path
                );
                assert!(
                    !audit.reason.trim().is_empty(),
                    "{label} traversal audit {} has empty reason",
                    audit.path
                );
                let source = audit.source.text();
                assert!(
                    source.contains(audit.evidence_marker),
                    "{label} traversal audit {} references missing marker {:?} in {}",
                    audit.path,
                    audit.evidence_marker,
                    audit.source.label()
                );
                match audit.kind {
                    TraversalAuditKind::CanonicalAstWalker => assert!(
                        audit.evidence_marker.contains("walk_ast_"),
                        "{label} canonical AST audit {} must point at a walk_ast_* call",
                        audit.path
                    ),
                    TraversalAuditKind::CanonicalFirWalker => assert!(
                        audit.evidence_marker.contains("walk_fir_"),
                        "{label} canonical FIR audit {} must point at a walk_fir_* call",
                        audit.path
                    ),
                    TraversalAuditKind::ExhaustiveSemantic
                    | TraversalAuditKind::StatementClassifier => {}
                }
            }
            for fixture in &contract.fixtures {
                assert!(
                    !fixture.surfaces.is_empty(),
                    "{label} fixture {} has no checked surfaces",
                    fixture.path
                );
                let full_path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(fixture.path);
                assert!(
                    full_path.exists(),
                    "{label} representative fixture missing: {}",
                    fixture.path
                );
            }
        }
    }

    #[test]
    fn compiler_pass_traversal_audits_classify_high_risk_paths() {
        let contracts = compiler_pass_contracts();
        let audit_rows: Vec<_> = contracts
            .iter()
            .flat_map(|contract| {
                contract
                    .traversal_audit
                    .iter()
                    .map(move |audit| (contract.id, audit))
            })
            .collect();

        let expected_paths = [
            "TypeChecker::check_stmt",
            "TypeChecker::check_expr",
            "TypeChecker::collect_declarations",
            "count_var_uses/count_var_uses_stmt",
            "count_consuming_uses_borrow_aware_impl",
            "RustCodegen::classify_imported_stmt_for_expansion",
            "RustCodegen::scan_declarations import expansion",
            "TypeInference::substitute_expr",
            "LoweringCtx::lower_stmt/lower_expr",
            "RustCodegen::collect_watch_type_names_from_stmt_list",
            "RustCodegen::emit_stmt/emit_expr",
            "RustCodegen::scan_declarations export pre-scan",
        ];

        for expected in expected_paths {
            assert!(
                audit_rows.iter().any(|(_, audit)| audit.path == expected),
                "missing traversal audit row for {expected}"
            );
        }

        for pass in [
            CompilerPassId::TypeChecking,
            CompilerPassId::OwnershipUseAnalysis,
            CompilerPassId::ImportResolution,
            CompilerPassId::FirLowering,
            CompilerPassId::RustCodegen,
        ] {
            assert!(
                audit_rows.iter().any(|(id, _)| *id == pass),
                "{} has no traversal audit rows",
                pass.label()
            );
        }

        assert!(
            audit_rows.iter().any(|(id, audit)| {
                *id == CompilerPassId::OwnershipUseAnalysis
                    && audit.kind == TraversalAuditKind::CanonicalAstWalker
            }),
            "ownership/use analysis should keep generic var-use counting on the canonical AST walker"
        );
        assert!(
            audit_rows.iter().any(|(id, audit)| {
                *id == CompilerPassId::FirLowering
                    && audit.kind == TraversalAuditKind::CanonicalFirWalker
            }),
            "FIR lowering should keep generic FIR substitution on the canonical FIR walker"
        );
        assert!(
            audit_rows.iter().any(|(id, audit)| {
                *id == CompilerPassId::RustCodegen
                    && audit.path == "RustCodegen::collect_watch_type_names_from_stmt_list"
                    && audit.kind == TraversalAuditKind::CanonicalAstWalker
            }),
            "Rust codegen watch discovery should use the canonical AST walker"
        );
        assert!(
            audit_rows.iter().any(|(id, audit)| {
                *id == CompilerPassId::ImportResolution
                    && audit.kind == TraversalAuditKind::StatementClassifier
            }),
            "import resolution should expose its statement classifier audit row"
        );
        assert!(
            audit_rows.iter().any(|(id, audit)| {
                *id == CompilerPassId::TypeChecking
                    && audit.kind == TraversalAuditKind::ExhaustiveSemantic
            }),
            "type checking should be explicitly classified as semantic traversal"
        );
    }

    #[test]
    fn compiler_pass_contract_coverage_markers_are_backed_by_matrix() {
        let ast_rows = ast_pass_coverage_cases();
        let fir_rows = fir_phase_coverage_cases();

        for contract in compiler_pass_contracts() {
            let label = contract.id.label();
            for coverage in &contract.coverage {
                match coverage {
                    PassCoverageExpectation::AstOwnership { row, markers } => {
                        assert!(
                            !markers.is_empty(),
                            "{label} AST ownership row {row} has no markers"
                        );
                        let ast_row = ast_rows
                            .iter()
                            .find(|candidate| candidate.label == *row)
                            .unwrap_or_else(|| {
                                panic!("{label} references missing AST coverage row {row}")
                            });
                        let analysis = OwnershipAnalysis::analyze_stmt_refs(
                            &[&ast_row.stmt],
                            &BTreeMap::new(),
                        );
                        for marker in *markers {
                            assert!(
                                ast_row.ownership_markers.contains(marker),
                                "{label} marker {marker} is not declared on AST row {row}"
                            );
                            assert!(
                                analysis.var_uses.get(*marker).copied().unwrap_or(0) >= 1,
                                "{label} ownership var-use traversal missed {marker} in {row}"
                            );
                            assert!(
                                analysis.consuming_uses.get(*marker).copied().unwrap_or(0) >= 1,
                                "{label} ownership consuming-use traversal missed {marker} in {row}"
                            );
                        }
                    }
                    PassCoverageExpectation::AstImportExpansion { row, expansion } => {
                        let ast_row = ast_rows
                            .iter()
                            .find(|candidate| candidate.label == *row)
                            .unwrap_or_else(|| {
                                panic!("{label} references missing import coverage row {row}")
                            });
                        assert_eq!(
                            ast_row.import_expansion, *expansion,
                            "{label} import expansion contract drifted for {row}"
                        );
                        assert_eq!(
                            RustCodegen::classify_imported_stmt_for_expansion(&ast_row.stmt),
                            *expansion,
                            "{label} import classifier drifted for {row}"
                        );
                    }
                    PassCoverageExpectation::FirPhase { row, markers } => {
                        assert!(!markers.is_empty(), "{label} FIR row {row} has no markers");
                        let fir_row = fir_rows
                            .iter()
                            .find(|candidate| candidate.label == *row)
                            .unwrap_or_else(|| {
                                panic!("{label} references missing FIR coverage row {row}")
                            });
                        assert_eq!(
                            fir_row.coverage,
                            FirPhaseCoverage::VisitsFirExpressions,
                            "{label} FIR contract row {row} must visit expressions"
                        );
                        let mut vars = BTreeSet::new();
                        collect_fir_visitor_vars_from_stmt(&fir_row.stmt, &mut vars);
                        for marker in *markers {
                            assert!(
                                vars.contains(*marker),
                                "{label} canonical FIR visitor missed {marker} in {row}; visited {vars:?}"
                            );
                        }
                    }
                    PassCoverageExpectation::FixtureText { path, marker } => {
                        assert!(
                            contract_fixture_text(path).contains(marker),
                            "{label} fixture {path} does not contain contract marker {marker:?}"
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn compiler_pass_contract_docs_track_checked_metadata() {
        let docs = contract_fixture_text("docs/compiler-pass-contracts.md");
        for contract in compiler_pass_contracts() {
            let label = contract.id.label();
            assert!(
                docs.contains(label),
                "docs/compiler-pass-contracts.md missing contract label {label}"
            );
            for audit in &contract.traversal_audit {
                assert!(
                    docs.contains(audit.path),
                    "docs/compiler-pass-contracts.md missing traversal audit path {} for {label}",
                    audit.path
                );
            }
            for fixture in &contract.fixtures {
                assert!(
                    docs.contains(fixture.path),
                    "docs/compiler-pass-contracts.md missing fixture path {} for {label}",
                    fixture.path
                );
            }
        }
    }

    struct StmtWildcardGuardRegion {
        file: &'static str,
        label: &'static str,
        source: &'static str,
        start_marker: &'static str,
        end_marker: &'static str,
    }

    fn high_risk_stmt_wildcard_guard_regions() -> Vec<StmtWildcardGuardRegion> {
        vec![
            StmtWildcardGuardRegion {
                file: "src/lib.rs",
                label: "TypeChecker::exported_names_from_stmts",
                source: include_str!("../lib.rs"),
                start_marker: "    fn exported_names_from_stmts(stmts: &[Stmt])",
                end_marker: "\n    fn import_path_span",
            },
            StmtWildcardGuardRegion {
                file: "src/lib.rs",
                label: "TypeChecker::collect_declarations",
                source: include_str!("../lib.rs"),
                start_marker: "    pub fn collect_declarations(&mut self, stmts: &[Stmt])",
                end_marker: "\n    /// Pass 2: check the program for errors",
            },
            StmtWildcardGuardRegion {
                file: "src/bin/runa.rs",
                label: "RustCodegen::collect_exported_names_from_stmts",
                source: include_str!("runa.rs"),
                start_marker: "    fn collect_exported_names_from_stmts(&self, stmts: &[Stmt])",
                end_marker: "\n    fn classify_imported_stmt_for_expansion",
            },
            StmtWildcardGuardRegion {
                file: "src/bin/runa.rs",
                label: "RustCodegen::scan_declarations import resolution",
                source: include_str!("runa.rs"),
                start_marker:
                    "        // Resolve @ import statements: parse imported .runa files and merge their definitions",
                end_marker: "        // Deduplicate type declarations from imports",
            },
            StmtWildcardGuardRegion {
                file: "src/bin/runa.rs",
                label: "RustCodegen::scan_declarations export pre-scan",
                source: include_str!("runa.rs"),
                start_marker: "        // Pre-scan: collect @ export annotations (M3b)",
                end_marker: "        // M26: Pre-scan for @ store / @ persist annotations",
            },
        ]
    }

    fn guarded_region_text<'a>(region: &'a StmtWildcardGuardRegion) -> (&'a str, usize) {
        let start = region.source.find(region.start_marker).unwrap_or_else(|| {
            panic!(
                "{} guard region missing start marker for {}",
                region.file, region.label
            )
        });
        let after_start = &region.source[start..];
        let end = after_start.find(region.end_marker).unwrap_or_else(|| {
            panic!(
                "{} guard region missing end marker for {}",
                region.file, region.label
            )
        });
        let start_line = region.source[..start].lines().count() + 1;
        (&after_start[..end], start_line)
    }

    fn broad_stmt_wildcard_ignore_violations(region: &str, start_line: usize) -> Vec<String> {
        let lines: Vec<&str> = region.lines().collect();
        let mut violations = Vec::new();
        for (idx, line) in lines.iter().enumerate() {
            let trimmed = line.trim_start();
            if !trimmed.starts_with("_ =>") {
                continue;
            }

            let mut snippet = trimmed.to_string();
            for next in lines.iter().skip(idx + 1).take(6) {
                if snippet.contains(',') {
                    break;
                }
                snippet.push_str(next.trim());
            }
            let compact: String = snippet.chars().filter(|ch| !ch.is_whitespace()).collect();
            let is_ignore = compact.starts_with("_=>{}")
                || compact.starts_with("_=>false")
                || compact.starts_with("_=>None")
                || compact.starts_with("_=>()");
            if is_ignore {
                violations.push(format!("line {}: {}", start_line + idx, trimmed));
            }
        }
        violations
    }

    #[test]
    fn broad_stmt_wildcard_guard_rejects_ignores_and_allows_explicit_arms() {
        let bad = r#"
match stmt {
    Stmt::Defn(_) => {}
    _ => {}
}
"#;
        assert_eq!(broad_stmt_wildcard_ignore_violations(bad, 1).len(), 1);

        let bad_false = r#"
match stmt {
    Stmt::Defn(_) => true,
    _ => false,
}
"#;
        assert_eq!(
            broad_stmt_wildcard_ignore_violations(bad_false, 10).len(),
            1
        );

        let explicit = r#"
match stmt {
    Stmt::Defn(_) => {}
    Stmt::TypeDecl(_) | Stmt::Abort | Stmt::Expr(_) => {}
}
"#;
        assert!(broad_stmt_wildcard_ignore_violations(explicit, 20).is_empty());

        let passthrough = r#"
match stmt {
    Stmt::Defn(_) => Some(stmt),
    _ => Some(stmt),
}
"#;
        assert!(broad_stmt_wildcard_ignore_violations(passthrough, 30).is_empty());
    }

    #[test]
    fn high_risk_stmt_regions_have_no_broad_wildcard_ignores() {
        let regions = high_risk_stmt_wildcard_guard_regions();
        assert!(
            regions.len() >= 5,
            "guard should cover TypeChecker and RustCodegen declaration/import/export regions"
        );

        let mut violations = Vec::new();
        for region in &regions {
            let (text, start_line) = guarded_region_text(region);
            for violation in broad_stmt_wildcard_ignore_violations(text, start_line) {
                violations.push(format!(
                    "{} {} has broad Stmt wildcard ignore: {}",
                    region.file, region.label, violation
                ));
            }
        }

        assert!(
            violations.is_empty(),
            "high-risk Stmt wildcard guard failed:\n{}",
            violations.join("\n")
        );
    }

    // ── Lowering tests ──────────────────────────────────────────────

    /// Helper: parse source, compute ownership, lower to FIR
    fn lower_source(source: &str) -> Vec<FirStmt> {
        let mut lexer = Lexer::new(source);
        let tokens = lexer.tokenize();
        let mut parser = Parser::new(tokens, source);
        let stmts = parser.parse_program().expect("parse failed");

        // Find the expression from a Bind statement
        let types = TypeRegistry::new();
        let copy_vars = BTreeSet::new();
        let ref_match = BTreeSet::new();

        // Compute ownership for the whole program
        let ownership = OwnershipAnalysis {
            var_uses: BTreeMap::new(),
            consuming_uses: BTreeMap::new(),
        };

        let mut ctx = LoweringCtx {
            type_env: BTreeMap::new(),
            inference: None,
            fn_schemes: BTreeMap::new(),
            types: &types,
            ownership: &ownership,
            copy_vars: &copy_vars,
            ref_match_bindings: &ref_match,
        };

        stmts.iter().map(|s| ctx.lower_stmt(s)).collect()
    }

    fn lower_stmt_via_fir_pipeline(
        stmt: &Stmt,
        types: &TypeRegistry,
        borrow_params: &BTreeMap<String, Vec<bool>>,
        copy_vars: &BTreeSet<String>,
        ref_match: &BTreeSet<String>,
    ) -> FirStmt {
        match stmt {
            Stmt::Defn(Defn::Fn {
                name, params, body, ..
            }) => {
                let mut type_env = BTreeMap::new();
                for p in params {
                    if let Some(ty) = &p.ty {
                        type_env.insert(
                            p.name.clone(),
                            LoweringCtx::ty_to_fir_with_registry(ty, types),
                        );
                    }
                }
                let param_names: Vec<&str> = params.iter().map(|p| p.name.as_str()).collect();
                let ownership = OwnershipAnalysis::analyze(
                    body,
                    borrow_params,
                    Some(name.as_str()),
                    &param_names,
                );
                let mut ctx = LoweringCtx {
                    type_env,
                    inference: None,
                    fn_schemes: BTreeMap::new(),
                    types,
                    ownership: &ownership,
                    copy_vars,
                    ref_match_bindings: ref_match,
                };
                ctx.lower_stmt(stmt)
            }
            Stmt::Bind(_, _, expr) | Stmt::Expr(expr) => {
                let ownership = OwnershipAnalysis::analyze_simple(expr);
                let mut ctx = LoweringCtx {
                    type_env: BTreeMap::new(),
                    inference: None,
                    fn_schemes: BTreeMap::new(),
                    types,
                    ownership: &ownership,
                    copy_vars,
                    ref_match_bindings: ref_match,
                };
                ctx.lower_stmt(stmt)
            }
            Stmt::For(_, iter_expr, _) => {
                let ownership = OwnershipAnalysis::analyze_simple(iter_expr);
                let mut ctx = LoweringCtx {
                    type_env: BTreeMap::new(),
                    inference: None,
                    fn_schemes: BTreeMap::new(),
                    types,
                    ownership: &ownership,
                    copy_vars,
                    ref_match_bindings: ref_match,
                };
                ctx.lower_stmt(stmt)
            }
            _ => {
                let ownership = OwnershipAnalysis {
                    var_uses: BTreeMap::new(),
                    consuming_uses: BTreeMap::new(),
                };
                let mut ctx = LoweringCtx {
                    type_env: BTreeMap::new(),
                    inference: None,
                    fn_schemes: BTreeMap::new(),
                    types,
                    ownership: &ownership,
                    copy_vars,
                    ref_match_bindings: ref_match,
                };
                ctx.lower_stmt(stmt)
            }
        }
    }

    fn lower_source_via_fir_pipeline(source: &str) -> Vec<FirStmt> {
        let mut lexer = Lexer::new(source);
        let tokens = lexer.tokenize();
        let mut parser = Parser::new(tokens, source);
        let stmts = parser.parse_program().expect("parse failed");
        let mut cg = RustCodegen::new();
        let resolved = cg.scan_declarations(&stmts);
        resolved
            .iter()
            .map(|stmt| {
                lower_stmt_via_fir_pipeline(
                    stmt,
                    &cg.types,
                    &cg.borrow_only_params,
                    &cg.copy_vars,
                    &cg.ref_match_bindings,
                )
            })
            .collect()
    }

    fn import_expr_snapshot(expr: &Expr) -> String {
        match &expr.kind {
            ExprKind::Var(name) => format!("var {}", name),
            ExprKind::Lit(Literal::Int(_)) => "lit Int".to_string(),
            ExprKind::Lit(Literal::Float(_)) => "lit Float".to_string(),
            ExprKind::Lit(Literal::Str(_)) => "lit String".to_string(),
            ExprKind::Lit(Literal::Char(_)) => "lit Char".to_string(),
            ExprKind::Lit(Literal::Bool(_)) => "lit Bool".to_string(),
            ExprKind::App(func, args) => {
                let head = match &func.kind {
                    ExprKind::Var(name) => name.clone(),
                    ExprKind::Field(_, field) => format!(".{}", field),
                    _ => "callable".to_string(),
                };
                format!("app {} /{}", head, args.len())
            }
            ExprKind::Lambda(params, _) => format!("lambda/{}", params.len()),
            ExprKind::BinOp(op, _, _) => format!("binop {}", op),
            ExprKind::UnOp(op, _) => format!("unop {}", op),
            ExprKind::If(_, _, _) => "if".to_string(),
            ExprKind::Match(_, _) => "match".to_string(),
            ExprKind::Block(_) => "block".to_string(),
            ExprKind::Field(_, field) => format!("field .{}", field),
            ExprKind::Index(_, _) => "index".to_string(),
            ExprKind::List(items) => format!("list/{}", items.len()),
            ExprKind::Tuple(items) => format!("tuple/{}", items.len()),
            ExprKind::Effect(name, args) => format!("effect {} /{}", name, args.len()),
            ExprKind::Handle { effect, .. } => format!("handle {}", effect),
            ExprKind::Try(_) => "try".to_string(),
            ExprKind::Conjunction(items) => format!("and/{}", items.len()),
            ExprKind::Disjunction(items) => format!("or/{}", items.len()),
            ExprKind::Pipe(_, _) => "pipe".to_string(),
            ExprKind::Unit => "unit".to_string(),
        }
    }

    fn import_annot_arg_snapshot(expr: &Expr) -> String {
        match &expr.kind {
            ExprKind::Var(name) => name.clone(),
            ExprKind::Lit(lit) => lit.to_string(),
            _ => import_expr_snapshot(expr),
        }
    }

    fn render_import_stmt_snapshot(stmt: &Stmt, indent: usize, out: &mut String) {
        let pad = "  ".repeat(indent);
        match stmt {
            Stmt::Defn(Defn::Fn { name, params, .. }) => {
                out.push_str(&format!("{}fn {}/{}\n", pad, name, params.len()));
            }
            Stmt::Defn(Defn::Actor { name, handlers, .. }) => {
                out.push_str(&format!("{}actor {}/{}\n", pad, name, handlers.len()));
            }
            Stmt::Defn(Defn::Module { name, body }) => {
                out.push_str(&format!("{}module {}\n", pad, name));
                for stmt in body {
                    render_import_stmt_snapshot(stmt, indent + 1, out);
                }
            }
            Stmt::TypeDecl(TypeDecl::ADT { name, variants, .. }) => {
                let variants = variants
                    .iter()
                    .map(|v| v.name.as_str())
                    .collect::<Vec<_>>()
                    .join(" | ");
                out.push_str(&format!("{}type {} = {}\n", pad, name, variants));
            }
            Stmt::TypeDecl(TypeDecl::WhenType { name, variants, .. }) => {
                let variants = variants
                    .iter()
                    .map(|v| v.name.as_str())
                    .collect::<Vec<_>>()
                    .join(" | ");
                out.push_str(&format!("{}when-type {} = {}\n", pad, name, variants));
            }
            Stmt::TypeDecl(TypeDecl::EffectDecl { name, ops }) => {
                out.push_str(&format!("{}effect {}/{}\n", pad, name, ops.len()));
            }
            Stmt::TypeDecl(TypeDecl::TraitDecl { name, methods, .. }) => {
                out.push_str(&format!("{}trait {}/{}\n", pad, name, methods.len()));
            }
            Stmt::TypeDecl(TypeDecl::ImplBlock {
                trait_name,
                for_type,
                methods,
            }) => {
                out.push_str(&format!(
                    "{}impl {}/{} for {}\n",
                    pad,
                    trait_name,
                    methods.len(),
                    for_type
                ));
            }
            Stmt::TypeDecl(TypeDecl::RuleScope { name, params, body }) => {
                out.push_str(&format!("{}rulescope {}/{}\n", pad, name, params.len()));
                for stmt in body {
                    render_import_stmt_snapshot(stmt, indent + 1, out);
                }
            }
            Stmt::Annot(name, args) => {
                if args.is_empty() {
                    out.push_str(&format!("{}@ {}\n", pad, name));
                } else {
                    let rendered = args
                        .iter()
                        .map(import_annot_arg_snapshot)
                        .collect::<Vec<_>>()
                        .join(", ");
                    out.push_str(&format!("{}@ {} {}\n", pad, name, rendered));
                }
            }
            Stmt::Bind(pat, ty, expr) => {
                let ty_suffix = ty
                    .as_ref()
                    .map(|ty| format!(": {}", ty))
                    .unwrap_or_default();
                out.push_str(&format!(
                    "{}bind {}{} = {}\n",
                    pad,
                    format_pat(pat),
                    ty_suffix,
                    import_expr_snapshot(expr)
                ));
            }
            Stmt::MonadicBind(pat, ty, expr) => {
                let ty_suffix = ty
                    .as_ref()
                    .map(|ty| format!(": {}", ty))
                    .unwrap_or_default();
                out.push_str(&format!(
                    "{}monadic-bind {}{} = {}\n",
                    pad,
                    format_pat(pat),
                    ty_suffix,
                    import_expr_snapshot(expr)
                ));
            }
            Stmt::StreamBind(name, expr) => {
                out.push_str(&format!(
                    "{}stream {} = {}\n",
                    pad,
                    name,
                    import_expr_snapshot(expr)
                ));
            }
            Stmt::Use(path) => out.push_str(&format!("{}use {}\n", pad, path)),
            Stmt::Import(path) => out.push_str(&format!("{}import {}\n", pad, path)),
            Stmt::QualifiedImport(name, path) => {
                out.push_str(&format!("{}qualified-import {} from {}\n", pad, name, path))
            }
            Stmt::HashImport(hash, path) => {
                out.push_str(&format!("{}hash-import #{} from {}\n", pad, hash, path))
            }
            Stmt::Depend(name, version) => {
                out.push_str(&format!("{}depend {} {}\n", pad, name, version))
            }
            Stmt::RustBlock(_) => out.push_str(&format!("{}rust-block\n", pad)),
            Stmt::Rule(Rule::Clause { .. }) => out.push_str(&format!("{}rule clause\n", pad)),
            Stmt::Rule(Rule::Default { .. }) => out.push_str(&format!("{}rule default\n", pad)),
            Stmt::Rule(Rule::Exception { label, .. }) => {
                out.push_str(&format!("{}rule exception {}\n", pad, label))
            }
            Stmt::Rule(Rule::ReactiveScope { name, body }) => {
                out.push_str(&format!("{}scope {}\n", pad, name));
                for stmt in body {
                    render_import_stmt_snapshot(stmt, indent + 1, out);
                }
            }
            Stmt::For(name, expr, body) => {
                out.push_str(&format!(
                    "{}for {} in {}\n",
                    pad,
                    name,
                    import_expr_snapshot(expr)
                ));
                for stmt in body {
                    render_import_stmt_snapshot(stmt, indent + 1, out);
                }
            }
            Stmt::While(expr, body) => {
                out.push_str(&format!("{}while {}\n", pad, import_expr_snapshot(expr)));
                for stmt in body {
                    render_import_stmt_snapshot(stmt, indent + 1, out);
                }
            }
            Stmt::Send(target, msg) => out.push_str(&format!(
                "{}send {} <- {}\n",
                pad,
                import_expr_snapshot(target),
                import_expr_snapshot(msg)
            )),
            Stmt::StreamSub(expr, arms) => out.push_str(&format!(
                "{}stream-sub {} arms={}\n",
                pad,
                import_expr_snapshot(expr),
                arms.len()
            )),
            Stmt::Invariant { name, subject, .. } => out.push_str(&format!(
                "{}invariant {} on {}\n",
                pad,
                name,
                import_expr_snapshot(subject)
            )),
            Stmt::Prove { name, .. } => out.push_str(&format!("{}prove {}\n", pad, name)),
            Stmt::Explore(query) => out.push_str(&format!(
                "{}explore {}\n",
                pad,
                query.name.as_deref().unwrap_or("anonymous")
            )),
            Stmt::Assert(name, args) => {
                out.push_str(&format!("{}assert {} /{}\n", pad, name, args.len()))
            }
            Stmt::Retract(name, args) => {
                out.push_str(&format!("{}retract {} /{}\n", pad, name, args.len()))
            }
            Stmt::Abort => out.push_str(&format!("{}abort\n", pad)),
            Stmt::Expr(expr) => {
                out.push_str(&format!("{}expr {}\n", pad, import_expr_snapshot(expr)));
            }
        }
    }

    fn render_import_normalization_snapshot(cg: &RustCodegen, stmts: &[Stmt]) -> String {
        let mut out = String::new();
        let exports = if cg.types.exported_names.is_empty() {
            "-".to_string()
        } else {
            cg.types
                .exported_names
                .iter()
                .cloned()
                .collect::<Vec<_>>()
                .join(", ")
        };
        out.push_str(&format!("exports: {}\n", exports));
        for (module, exports) in &cg.types.module_exports {
            let rendered = if exports.is_empty() {
                "-".to_string()
            } else {
                exports.iter().cloned().collect::<Vec<_>>().join(", ")
            };
            out.push_str(&format!("module-exports {}: {}\n", module, rendered));
        }
        for stmt in stmts {
            render_import_stmt_snapshot(stmt, 0, &mut out);
        }
        out
    }

    fn import_normalization_snapshot_for_source(source: &str, filename: Option<&str>) -> String {
        let mut lexer = Lexer::new(source);
        let tokens = lexer.tokenize();
        let mut parser = Parser::new(tokens, source);
        let stmts = parser.parse_program().expect("parse failed");
        let mut cg = RustCodegen::new();
        if let Some(filename) = filename {
            cg.source_dir = source_dir_for(filename);
            cg.source_name = Some(filename.to_string());
        }
        let resolved = cg.scan_declarations(&stmts);
        render_import_normalization_snapshot(&cg, &resolved)
    }

    fn fir_ty_snapshot(ty: &FirTy) -> String {
        match ty {
            FirTy::Int => "Int".to_string(),
            FirTy::Float => "Float".to_string(),
            FirTy::Bool => "Bool".to_string(),
            FirTy::Char => "Char".to_string(),
            FirTy::String => "String".to_string(),
            FirTy::Unit => "()".to_string(),
            FirTy::List(inner) => format!("List({})", fir_ty_snapshot(inner)),
            FirTy::Option(inner) => format!("Option({})", fir_ty_snapshot(inner)),
            FirTy::Result(ok, err) => {
                format!("Result({}, {})", fir_ty_snapshot(ok), fir_ty_snapshot(err))
            }
            FirTy::Tuple(elems) => format!(
                "Tuple({})",
                elems
                    .iter()
                    .map(fir_ty_snapshot)
                    .collect::<Vec<_>>()
                    .join(", ")
            ),
            FirTy::Map(k, v) => format!("Map({}, {})", fir_ty_snapshot(k), fir_ty_snapshot(v)),
            FirTy::Set(inner) => format!("Set({})", fir_ty_snapshot(inner)),
            FirTy::Named(name) => name.clone(),
            FirTy::Arrow(a, b) => format!("({} -> {})", fir_ty_snapshot(a), fir_ty_snapshot(b)),
            FirTy::Var(id) => format!("Var({id})"),
            FirTy::Unknown => "Unknown".to_string(),
        }
    }

    fn fir_expr_snapshot(expr: &FirExpr, indent: usize, out: &mut String) {
        let pad = "  ".repeat(indent);
        match &expr.kind {
            FirExprKind::Var(name, mode) => {
                out.push_str(&format!(
                    "{}var {} {:?}: {}\n",
                    pad,
                    name,
                    mode,
                    fir_ty_snapshot(&expr.ty)
                ));
            }
            FirExprKind::Lit(lit) => {
                out.push_str(&format!(
                    "{}lit {:?}: {}\n",
                    pad,
                    lit,
                    fir_ty_snapshot(&expr.ty)
                ));
            }
            FirExprKind::App(func, args) => {
                out.push_str(&format!("{}app: {}\n", pad, fir_ty_snapshot(&expr.ty)));
                fir_expr_snapshot(func, indent + 1, out);
                for arg in args {
                    fir_expr_snapshot(arg, indent + 1, out);
                }
            }
            FirExprKind::Lambda(params, body) => {
                let params = params
                    .iter()
                    .map(|p| {
                        let ty =
                            p.ty.as_ref()
                                .map(|ty| emit_fir_ty_as_rust(ty))
                                .unwrap_or_else(|| "_".to_string());
                        format!("{}: {}", p.name, ty)
                    })
                    .collect::<Vec<_>>()
                    .join(", ");
                out.push_str(&format!(
                    "{}lambda [{}]: {}\n",
                    pad,
                    params,
                    fir_ty_snapshot(&expr.ty)
                ));
                fir_expr_snapshot(body, indent + 1, out);
            }
            FirExprKind::BinOp(op, lhs, rhs) => {
                out.push_str(&format!(
                    "{}binop {}: {}\n",
                    pad,
                    op,
                    fir_ty_snapshot(&expr.ty)
                ));
                fir_expr_snapshot(lhs, indent + 1, out);
                fir_expr_snapshot(rhs, indent + 1, out);
            }
            FirExprKind::UnOp(op, inner) => {
                out.push_str(&format!(
                    "{}unop {}: {}\n",
                    pad,
                    op,
                    fir_ty_snapshot(&expr.ty)
                ));
                fir_expr_snapshot(inner, indent + 1, out);
            }
            FirExprKind::If(cond, then_, else_) => {
                out.push_str(&format!("{}if: {}\n", pad, fir_ty_snapshot(&expr.ty)));
                fir_expr_snapshot(cond, indent + 1, out);
                fir_expr_snapshot(then_, indent + 1, out);
                fir_expr_snapshot(else_, indent + 1, out);
            }
            FirExprKind::Match(scrutinee, arms) => {
                out.push_str(&format!("{}match: {}\n", pad, fir_ty_snapshot(&expr.ty)));
                fir_expr_snapshot(scrutinee, indent + 1, out);
                for arm in arms {
                    out.push_str(&format!("{}  arm {}\n", pad, format_pat(&arm.pat)));
                    if let Some(guard) = &arm.guard {
                        out.push_str(&format!("{}    guard\n", pad));
                        fir_expr_snapshot(guard, indent + 3, out);
                    }
                    fir_expr_snapshot(&arm.body, indent + 2, out);
                }
            }
            FirExprKind::Block(stmts) => {
                out.push_str(&format!("{}block: {}\n", pad, fir_ty_snapshot(&expr.ty)));
                for stmt in stmts {
                    fir_stmt_snapshot(stmt, indent + 1, out);
                }
            }
            FirExprKind::Field(base, field) => {
                out.push_str(&format!(
                    "{}field .{}: {}\n",
                    pad,
                    field,
                    fir_ty_snapshot(&expr.ty)
                ));
                fir_expr_snapshot(base, indent + 1, out);
            }
            FirExprKind::Index(base, idx) => {
                out.push_str(&format!("{}index: {}\n", pad, fir_ty_snapshot(&expr.ty)));
                fir_expr_snapshot(base, indent + 1, out);
                fir_expr_snapshot(idx, indent + 1, out);
            }
            FirExprKind::List(elems) => {
                out.push_str(&format!("{}list: {}\n", pad, fir_ty_snapshot(&expr.ty)));
                for elem in elems {
                    fir_expr_snapshot(elem, indent + 1, out);
                }
            }
            FirExprKind::Tuple(elems) => {
                out.push_str(&format!("{}tuple: {}\n", pad, fir_ty_snapshot(&expr.ty)));
                for elem in elems {
                    fir_expr_snapshot(elem, indent + 1, out);
                }
            }
            FirExprKind::Effect(name, args) => {
                out.push_str(&format!(
                    "{}effect {}: {}\n",
                    pad,
                    name,
                    fir_ty_snapshot(&expr.ty)
                ));
                for arg in args {
                    fir_expr_snapshot(arg, indent + 1, out);
                }
            }
            FirExprKind::Handle {
                effect,
                handlers,
                body,
            } => {
                out.push_str(&format!(
                    "{}handle {}: {}\n",
                    pad,
                    effect,
                    fir_ty_snapshot(&expr.ty)
                ));
                for handler in handlers {
                    out.push_str(&format!(
                        "{}  handler {}({})\n",
                        pad,
                        handler.op_name,
                        handler.params.join(", ")
                    ));
                    fir_expr_snapshot(&handler.body, indent + 2, out);
                }
                fir_expr_snapshot(body, indent + 1, out);
            }
            FirExprKind::Try(inner) => {
                out.push_str(&format!("{}try: {}\n", pad, fir_ty_snapshot(&expr.ty)));
                fir_expr_snapshot(inner, indent + 1, out);
            }
            FirExprKind::Conjunction(goals) => {
                out.push_str(&format!(
                    "{}conjunction: {}\n",
                    pad,
                    fir_ty_snapshot(&expr.ty)
                ));
                for goal in goals {
                    fir_expr_snapshot(goal, indent + 1, out);
                }
            }
            FirExprKind::Disjunction(goals) => {
                out.push_str(&format!(
                    "{}disjunction: {}\n",
                    pad,
                    fir_ty_snapshot(&expr.ty)
                ));
                for goal in goals {
                    fir_expr_snapshot(goal, indent + 1, out);
                }
            }
            FirExprKind::Pipe(lhs, rhs) => {
                out.push_str(&format!("{}pipe: {}\n", pad, fir_ty_snapshot(&expr.ty)));
                fir_expr_snapshot(lhs, indent + 1, out);
                fir_expr_snapshot(rhs, indent + 1, out);
            }
            FirExprKind::Unit => {
                out.push_str(&format!("{}unit: {}\n", pad, fir_ty_snapshot(&expr.ty)));
            }
        }
    }

    fn fir_stmt_snapshot(stmt: &FirStmt, indent: usize, out: &mut String) {
        let pad = "  ".repeat(indent);
        match stmt {
            FirStmt::TypeDecl(TypeDecl::ADT {
                name,
                params,
                variants,
                ..
            }) => {
                let params = if params.is_empty() {
                    String::new()
                } else {
                    format!(
                        "<{}>",
                        params
                            .iter()
                            .map(|p| p.name.clone())
                            .collect::<Vec<_>>()
                            .join(", ")
                    )
                };
                let variants = variants
                    .iter()
                    .map(|variant| {
                        if variant.fields.is_empty() {
                            variant.name.clone()
                        } else if variant.positional {
                            format!(
                                "{}({})",
                                variant.name,
                                variant
                                    .fields
                                    .iter()
                                    .map(|field| emit_fir_ty_as_rust(&field.ty))
                                    .collect::<Vec<_>>()
                                    .join(", ")
                            )
                        } else {
                            format!(
                                "{}({})",
                                variant.name,
                                variant
                                    .fields
                                    .iter()
                                    .map(|field| format!(
                                        "{}: {}",
                                        field.name,
                                        emit_fir_ty_as_rust(&field.ty)
                                    ))
                                    .collect::<Vec<_>>()
                                    .join(", ")
                            )
                        }
                    })
                    .collect::<Vec<_>>()
                    .join(" | ");
                out.push_str(&format!("{}type {}{} = {}\n", pad, name, params, variants));
            }
            FirStmt::Defn(FirDefn::Fn {
                name,
                params,
                ret_ty,
                body,
                ..
            }) => {
                let params = params
                    .iter()
                    .map(|p| {
                        let ty =
                            p.ty.as_ref()
                                .map(emit_fir_ty_as_rust)
                                .unwrap_or_else(|| "_".to_string());
                        format!("{}: {}", p.name, ty)
                    })
                    .collect::<Vec<_>>()
                    .join(", ");
                let ret = ret_ty
                    .as_ref()
                    .map(emit_fir_ty_as_rust)
                    .unwrap_or_else(|| "_".to_string());
                out.push_str(&format!("{}fn {}({}) -> {}\n", pad, name, params, ret));
                fir_expr_snapshot(body, indent + 1, out);
            }
            FirStmt::Bind(pat, _, expr) => {
                out.push_str(&format!("{}bind {}\n", pad, format_pat(pat)));
                fir_expr_snapshot(expr, indent + 1, out);
            }
            FirStmt::Expr(expr) => {
                out.push_str(&format!("{}expr\n", pad));
                fir_expr_snapshot(expr, indent + 1, out);
            }
            other => {
                out.push_str(&format!("{}{:?}\n", pad, other));
            }
        }
    }

    fn render_fir_snapshot(stmts: &[FirStmt]) -> String {
        let mut out = String::new();
        for stmt in stmts {
            fir_stmt_snapshot(stmt, 0, &mut out);
        }
        out
    }

    fn fir_ty_has_unresolved_holes(ty: &FirTy) -> bool {
        match ty {
            FirTy::Unknown | FirTy::Var(_) => true,
            FirTy::List(inner) | FirTy::Option(inner) | FirTy::Set(inner) => {
                fir_ty_has_unresolved_holes(inner)
            }
            FirTy::Result(ok, err) | FirTy::Map(ok, err) | FirTy::Arrow(ok, err) => {
                fir_ty_has_unresolved_holes(ok) || fir_ty_has_unresolved_holes(err)
            }
            FirTy::Tuple(elems) => elems.iter().any(fir_ty_has_unresolved_holes),
            FirTy::Int
            | FirTy::Float
            | FirTy::Bool
            | FirTy::Char
            | FirTy::String
            | FirTy::Unit
            | FirTy::Named(_) => false,
        }
    }

    fn assert_fir_expr_phase_validated(expr: &FirExpr, allow_callable_unknown: bool) {
        if !allow_callable_unknown {
            assert!(
                !fir_ty_has_unresolved_holes(&expr.ty),
                "unexpected unresolved FIR type in expression: {:?}",
                expr
            );
        }
        match &expr.kind {
            FirExprKind::App(func, args) => {
                assert_fir_expr_phase_validated(func, true);
                for arg in args {
                    assert_fir_expr_phase_validated(arg, false);
                }
            }
            FirExprKind::Lambda(_, _)
            | FirExprKind::BinOp(_, _, _)
            | FirExprKind::UnOp(_, _)
            | FirExprKind::If(_, _, _)
            | FirExprKind::Match(_, _)
            | FirExprKind::Block(_)
            | FirExprKind::Field(_, _)
            | FirExprKind::Index(_, _)
            | FirExprKind::List(_)
            | FirExprKind::Tuple(_)
            | FirExprKind::Effect(_, _)
            | FirExprKind::Handle { .. }
            | FirExprKind::Try(_)
            | FirExprKind::Conjunction(_)
            | FirExprKind::Disjunction(_)
            | FirExprKind::Pipe(_, _)
            | FirExprKind::Var(_, _)
            | FirExprKind::Lit(_)
            | FirExprKind::Unit => {
                visit_fir_expr_children(expr, &mut |child| match child {
                    FirChild::Expr(expr) => assert_fir_expr_phase_validated(expr, false),
                    FirChild::Stmt(stmt) => assert_fir_stmt_phase_validated(stmt),
                });
            }
        }
    }

    fn assert_fir_stmt_phase_validated(stmt: &FirStmt) {
        visit_fir_stmt_children(stmt, &mut |child| match child {
            FirChild::Expr(expr) => assert_fir_expr_phase_validated(expr, false),
            FirChild::Stmt(stmt) => assert_fir_stmt_phase_validated(stmt),
        });
    }

