    fn fir_var(name: &str, mode: VarMode) -> FirExpr {
        FirExpr {
            kind: FirExprKind::Var(name.into(), mode),
            span: Span::dummy(),
            ty: FirTy::Unknown,
        }
    }
    fn fir_int(n: i64) -> FirExpr {
        FirExpr {
            kind: FirExprKind::Lit(Literal::Int(n)),
            span: Span::dummy(),
            ty: FirTy::Int,
        }
    }
    fn fir_str(s: &str) -> FirExpr {
        FirExpr {
            kind: FirExprKind::Lit(Literal::Str(s.into())),
            span: Span::dummy(),
            ty: FirTy::String,
        }
    }

