    #[test]
    fn ownership_analysis_counts_repeated_self_recursive_passthrough_args() {
        let source =
            "> visit(expr: String, env: String) -> String { visit(expr, env) + visit(expr, env) }";
        let mut lexer = Lexer::new(source);
        let tokens = lexer.tokenize();
        let mut parser = Parser::new(tokens, source);
        let stmts = parser.parse_program().expect("parse failed");
        let Stmt::Defn(Defn::Fn { body, .. }) = &stmts[0] else {
            panic!("expected function definition");
        };

        let ownership =
            OwnershipAnalysis::analyze(body, &BTreeMap::new(), Some("visit"), &["expr", "env"]);
        assert_eq!(
            ownership.consuming_uses.get("env").copied().unwrap_or(0),
            2,
            "reused self-recursive passthrough args must still count as consuming for clone decisions"
        );
    }

    #[test]
    fn field_ty_supports_numeric_tuple_indices() {
        let ctx = LoweringCtx {
            type_env: BTreeMap::new(),
            inference: None,
            fn_schemes: BTreeMap::new(),
            types: &TypeRegistry::new(),
            ownership: &OwnershipAnalysis {
                var_uses: BTreeMap::new(),
                consuming_uses: BTreeMap::new(),
            },
            copy_vars: &BTreeSet::new(),
            ref_match_bindings: &BTreeSet::new(),
        };

        let tuple_ty = FirTy::Tuple(vec![FirTy::String, FirTy::Int, FirTy::Float]);
        assert_eq!(ctx.field_ty(&tuple_ty, "trd"), FirTy::Float);
        assert_eq!(ctx.field_ty(&tuple_ty, "0"), FirTy::String);
        assert_eq!(ctx.field_ty(&tuple_ty, "1"), FirTy::Int);
        assert_eq!(ctx.field_ty(&tuple_ty, "2"), FirTy::Float);
    }

